# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, Iterator, List

from hourglass.merging import merge_spans
from hourglass.models import Span

def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"

def _check_inside(worked: Iterable[Span], hours: Span):
    for item in worked:
        if item.start < hours.start or item.end > hours.end:
            raise ValueError(f"outside hours: {item}")

def _uncovered(worked, hours: Span) -> Iterator[Span]:
    cursor = hours.start
    for item in merge_spans(worked):
        if item.start > cursor:
            yield Span(cursor, item.start)
        cursor = item.end
    if cursor < hours.end:
        yield Span(cursor, hours.end)

def _label(gap: Span) -> str:
    start, stop = _clock(gap.start), _clock(gap.end)
    return f"gap {start}-{stop} ({gap.minutes} min)"

# ---
def find_gaps(
    worked: Iterable[Span], hours: Span
) -> List[str]:
    """One label per stretch of hours nobody covers."""
    worked = list(worked)
    _check_inside(worked, hours)
    gaps = _uncovered(worked, hours)
    return [_label(gap) for gap in gaps]
